def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    seen.add((r,c)); q=[(r,c)]
    for y,x in q:
     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      a,b=y+dy,x+dx
      if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
       seen.add((a,b)); q.append((a,b))
    objs.append(q)
 objs.sort(key=lambda q:min(x for y,x in q))
 out=[[0]*w for _ in range(h)]
 for i,q in enumerate(objs):
  lo=min(x for y,x in q); hi=max(x for y,x in q)
  shift=-lo if i==0 else w-1-hi
  for y,x in q: out[y][x+shift]=grid[y][x]
 return out

